    {
        $this->controlBracePolicy['getFinalControlContinuationTokensForOpeningToken'] = 1;
        if (T_IF === $openingTokenKind) {
            return [T_ELSE];
        }

        if (T_TRY === $openingTokenKind) {
            return [T_FINALLY];
        }

        return [];
    }


